INSERT INTO `email_templates` (`id`, `name`, `slug`, `category`, `subject`, `body`, `variables`) VALUES
(1, 'Успешна регистрация', 'auth.register', 'Автентикация', 'Добре дошли във Flex CMS, {{username}}!', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n    <meta charset=\"utf-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <style>\r\n        body {\r\n            margin: 0;\r\n            padding: 0;\r\n            font-family: \'Segoe UI\', Tahoma, Geneva, Verdana, sans-serif;\r\n            background-color: #f9fafb;\r\n        }\r\n        .wrapper {\r\n            width: 100%;\r\n            background-color: #f9fafb;\r\n            padding: 40px 20px;\r\n        }\r\n        .container {\r\n            max-width: 500px;\r\n            background-color: #ffffff;\r\n            margin: 0 auto;\r\n            border-radius: 12px;\r\n            overflow: hidden;\r\n            box-shadow: 0 4px 6px rgba(0,0,0,0.05);\r\n        }\r\n        .header-accent {\r\n            height: 6px;\r\n            background: linear-gradient(90deg, #007bff, #6610f2);\r\n            width: 100%;\r\n        }\r\n        .inner-padding {\r\n            padding: 40px;\r\n        }\r\n        .title {\r\n            color: #1a1a1a;\r\n            font-size: 26px;\r\n            font-weight: 700;\r\n            margin-bottom: 20px;\r\n            letter-spacing: -0.5px;\r\n        }\r\n        .content {\r\n            color: #4a4a4a;\r\n            font-size: 16px;\r\n            line-height: 1.7;\r\n            margin-bottom: 30px;\r\n        }\r\n        .button {\r\n            background-color: #007bff;\r\n            color: #ffffff !important;\r\n            padding: 14px 28px;\r\n            text-decoration: none;\r\n            border-radius: 8px;\r\n            font-weight: 600;\r\n            display: inline-block;\r\n            transition: background 0.3s;\r\n        }\r\n        .footer {\r\n            color: #999999;\r\n            font-size: 13px;\r\n            text-align: center;\r\n            padding: 30px;\r\n            background-color: #fcfcfc;\r\n            border-top: 1px solid #eeeeee;\r\n        }\r\n    </style>\r\n</head>\r\n<body>\r\n    <table role=\"presentation\" class=\"wrapper\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">\r\n        <tr>\r\n            <td align=\"center\">\r\n                <table class=\"container\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">\r\n                    <tr><td><div class=\"header-accent\"></div>\r\n                    </td></tr>\r\n                    <tr>\r\n                        <td class=\"inner-padding\">\r\n                            <div class=\"title\">\r\n                                Добре дошли в нашия екип!\r\n                            </div>\r\n                            <div class=\"content\">\r\n                                Здравейте, <strong>{{user_name}}</strong>!<br><br>\r\n                                Радваме се да Ви видим тук! Вашият акаунт е успешно активиран и вече можете да се възползвате от всички възможности на нашата платформа.\r\n                            </div>\r\n                            <div align=\"center\">\r\n                                <a href=\"{{account}}\" class=\"button\">Към Вашия профил</a>\r\n                            </div>\r\n                        </td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td class=\"footer\">\r\n                            Това е автоматично съобщение. Ако имате въпроси, отговорете директно на този имейл.<br>\r\n                            &copy; 2026 Име на Вашата компания\r\n                        </td>\r\n                    </tr>\r\n                </table>\r\n            </td>\r\n        </tr>\r\n    </table>\r\n</body>\r\n</html>', '\"[{\\\"key\\\":\\\"user_name\\\",\\\"label\\\":\\\"\\\\u0418\\\\u043c\\\\u0435 \\\\u043d\\\\u0430 \\\\u043d\\\\u043e\\\\u0432\\\\u0438\\\\u044f \\\\u043f\\\\u043e\\\\u0442\\\\u0440\\\\u0435\\\\u0431\\\\u0438\\\\u0442\\\\u0435\\\\u043b.\\\"},{\\\"key\\\":\\\"account\\\",\\\"label\\\":\\\"\\\\u0411\\\\u044a\\\\u0440\\\\u0437\\\\u0430 \\\\u0432\\\\u0440\\\\u044a\\\\u0437\\\\u043a\\\\u0430 \\\\u043a\\\\u044a\\\\u043c \\\\u043f\\\\u0440\\\\u043e\\\\u0444\\\\u0438\\\\u043b\\\\u0430 \\\\u043d\\\\u0430 \\\\u043f\\\\u043e\\\\u0442\\\\u0440\\\\u0435\\\\u0431\\\\u0438\\\\u0442\\\\u0435\\\\u043b\\\\u044f.\\\"}]\"'),
(2, 'Забравена парола', 'auth.password_reset', 'Автентикация', 'Възстановяване на паролаss', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>Нулиране на парола</title>\r\n    <style>\r\n        /* Слагаме стиловете тук, за да са вградени в шаблона */\r\n        body {\r\n            font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\r\n            background-color: #f8fafc;\r\n            margin: 0;\r\n            padding: 0;\r\n        }\r\n        .container {\r\n            max-width: 500px;\r\n            margin: 40px auto;\r\n            background: #ffffff;\r\n            border-radius: 8px;\r\n            overflow: hidden;\r\n            border: 1px solid #e2e8f0;\r\n        }\r\n        .content {\r\n            padding: 32px;\r\n        }\r\n        h2 {\r\n            color: #1e293b;\r\n            margin-top: 0;\r\n        }\r\n        p {\r\n            color: #475569;\r\n            font-size: 16px;\r\n            line-height: 24px;\r\n        }\r\n        .btn-wrapper {\r\n            text-align: center;\r\n            margin: 32px 0;\r\n        }\r\n        .btn {\r\n            background-color: #3b82f6;\r\n            color: #ffffff !important;\r\n            padding: 14px 28px;\r\n            text-decoration: none;\r\n            border-radius: 6px;\r\n            font-weight: bold;\r\n            display: inline-block;\r\n        }\r\n        .footer {\r\n            padding: 20px;\r\n            background: #f1f5f9;\r\n            text-align: center;\r\n            font-size: 12px;\r\n            color: #64748b;\r\n        }\r\n        .link-text {\r\n            word-break: break-all;\r\n            color: #64748b;\r\n        }\r\n    </style>\r\n</head>\r\n<body>\r\n    <div class=\"container\">\r\n        <div class=\"content\">\r\n            <h2>Нулиране на паролата</h2>\r\n            <p>\r\n                Здравейте,\r\n            </p>\r\n            <p>\r\n                Получихме заявка за промяна на вашата парола. Ако не сте вие, моля игнорирайте този имейл.\r\n            </p>\r\n\r\n            <div class=\"btn-wrapper\">\r\n                <a href=\"{{reset_url}}\" class=\"btn\">Нулирай паролата</a>\r\n            </div>\r\n\r\n            <p>\r\n                Този линк ще бъде активен в следващите 60 минути.\r\n            </p>\r\n        </div>\r\n        <div class=\"footer\">\r\n            Ако имате проблеми, копирайте този линк във вашия браузър:<br>\r\n            <span class=\"link-text\">{{reset_url}}</span>\r\n        </div>\r\n    </div>\r\n</body>\r\n</html>', '\"[{\\\"key\\\":\\\"reset_url\\\",\\\"label\\\":\\\"\\\\u041b\\\\u0438\\\\u043d\\\\u043a \\\\u0437\\\\u0430 \\\\u043d\\\\u0443\\\\u043b\\\\u0438\\\\u0440\\\\u0430\\\\u043d\\\\u0435 \\\\u043d\\\\u0430 \\\\u043f\\\\u0430\\\\u0440\\\\u043e\\\\u043b\\\\u0430\\\\u0442\\\\u0430 (\\\\u0438\\\\u0437\\\\u043f\\\\u043e\\\\u043b\\\\u0437\\\\u0432\\\\u0430\\\\u0439 \\\\u0433\\\\u043e \\\\u0432 \\\\u0431\\\\u0443\\\\u0442\\\\u043e\\\\u043d \\\\u0438\\\\u043b\\\\u0438 \\\\u0445\\\\u0438\\\\u043f\\\\u0435\\\\u0440\\\\u0432\\\\u0440\\\\u044a\\\\u0437\\\\u043a\\\\u0430).\\\"}]\"'),
(5, 'Успешна регистрация', 'success-registration', 'Автентикация', 'Успешна регистрация', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n    <meta charset=\"utf-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <style>\r\n        body {\r\n            margin: 0;\r\n            padding: 0;\r\n            font-family: \'Segoe UI\', Tahoma, Geneva, Verdana, sans-serif;\r\n            background-color: #f9fafb;\r\n        }\r\n        .wrapper {\r\n            width: 100%;\r\n            background-color: #f9fafb;\r\n            padding: 40px 20px;\r\n        }\r\n        .container {\r\n            max-width: 500px;\r\n            background-color: #ffffff;\r\n            margin: 0 auto;\r\n            border-radius: 12px;\r\n            overflow: hidden;\r\n            box-shadow: 0 4px 6px rgba(0,0,0,0.05);\r\n        }\r\n        .header-accent {\r\n            height: 6px;\r\n            background: linear-gradient(90deg, #007bff, #6610f2);\r\n            width: 100%;\r\n        }\r\n        .inner-padding {\r\n            padding: 40px;\r\n        }\r\n        .title {\r\n            color: #1a1a1a;\r\n            font-size: 26px;\r\n            font-weight: 700;\r\n            margin-bottom: 20px;\r\n            letter-spacing: -0.5px;\r\n        }\r\n        .content {\r\n            color: #4a4a4a;\r\n            font-size: 16px;\r\n            line-height: 1.7;\r\n            margin-bottom: 30px;\r\n        }\r\n        .button {\r\n            background-color: #007bff;\r\n            color: #ffffff !important;\r\n            padding: 14px 28px;\r\n            text-decoration: none;\r\n            border-radius: 8px;\r\n            font-weight: 600;\r\n            display: inline-block;\r\n            transition: background 0.3s;\r\n        }\r\n        .footer {\r\n            color: #999999;\r\n            font-size: 13px;\r\n            text-align: center;\r\n            padding: 30px;\r\n            background-color: #fcfcfc;\r\n            border-top: 1px solid #eeeeee;\r\n        }\r\n    </style>\r\n</head>\r\n<body>\r\n    <table role=\"presentation\" class=\"wrapper\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">\r\n        <tr>\r\n            <td align=\"center\">\r\n                <table class=\"container\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">\r\n                    <tr><td><div class=\"header-accent\"></div>\r\n                    </td></tr>\r\n                    <tr>\r\n                        <td class=\"inner-padding\">\r\n                            <div class=\"title\">\r\n                                Паролата е променена успешно\r\n                            </div>\r\n                            <div class=\"content\">\r\n                                Здравейте, <strong>{{user_name}}</strong>!<br><br>\r\n                                Уведомяваме Ви, че паролата за Вашия акаунт беше променена успешно. Ако това сте направили Вие, не е необходимо да предприемате никакви действия.<br><br>\r\n                                Ако не сте извършили тази промяна, моля, незабавно се свържете с нас или защитете акаунта си чрез линка по-долу.\r\n                            </div>\r\n                            <div align=\"center\">\r\n                                <a href=\"{{security_link}}\" class=\"button\">Защити моя акаунт</a>\r\n                            </div>\r\n                        </td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td class=\"footer\">\r\n                            Това е автоматично съобщение за сигурност. Ако имате въпроси, отговорете на този имейл.<br>\r\n                            &copy; 2026 Име на Вашата компания\r\n                        </td>\r\n                    </tr>\r\n                </table>\r\n            </td>\r\n        </tr>\r\n    </table>\r\n</body>\r\n</html>', '\"[{\\\"key\\\":\\\"user_name\\\",\\\"label\\\":\\\"\\\\u0418\\\\u043c\\\\u0435\\\\u0442\\\\u043e \\\\u043d\\\\u0430 \\\\u043f\\\\u043e\\\\u043b\\\\u0443\\\\u0447\\\\u0430\\\\u0442\\\\u0435\\\\u043b\\\\u044f \\\\u0437\\\\u0430 \\\\u043f\\\\u0435\\\\u0440\\\\u0441\\\\u043e\\\\u043d\\\\u0430\\\\u043b\\\\u0438\\\\u0437\\\\u0438\\\\u0440\\\\u0430\\\\u043d\\\\u043e \\\\u043e\\\\u0431\\\\u0440\\\\u044a\\\\u0449\\\\u0435\\\\u043d\\\\u0438\\\\u0435.\\\"},{\\\"key\\\":\\\"security_link\\\",\\\"label\\\":\\\"URL \\\\u0430\\\\u0434\\\\u0440\\\\u0435\\\\u0441 \\\\u0437\\\\u0430 \\\\u0434\\\\u043e\\\\u0441\\\\u0442\\\\u044a\\\\u043f \\\\u0434\\\\u043e \\\\u043d\\\\u0430\\\\u0441\\\\u0442\\\\u0440\\\\u043e\\\\u0439\\\\u043a\\\\u0438\\\\u0442\\\\u0435 \\\\u0437\\\\u0430 \\\\u0441\\\\u0438\\\\u0433\\\\u0443\\\\u0440\\\\u043d\\\\u043e\\\\u0441\\\\u0442 \\\\u043d\\\\u0430 \\\\u0430\\\\u043a\\\\u0430\\\\u0443\\\\u043d\\\\u0442\\\\u0430.\\\"}]\"'),
(6, 'Потвърждение на имейл', 'email-confirmation', 'Автентикация', 'Потвърждение на имейл', '<!DOCTYPE html>\r\n<html>\r\n<head>\r\n    <meta charset=\"utf-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <style>\r\n        body {\r\n            margin: 0;\r\n            padding: 0;\r\n            font-family: \'Segoe UI\', Tahoma, Geneva, Verdana, sans-serif;\r\n            background-color: #f9fafb;\r\n        }\r\n        .wrapper {\r\n            width: 100%;\r\n            background-color: #f9fafb;\r\n            padding: 40px 20px;\r\n        }\r\n        .container {\r\n            max-width: 500px;\r\n            background-color: #ffffff;\r\n            margin: 0 auto;\r\n            border-radius: 12px;\r\n            overflow: hidden;\r\n            box-shadow: 0 4px 6px rgba(0,0,0,0.05);\r\n        }\r\n        .header-accent {\r\n            height: 6px;\r\n            background: linear-gradient(90deg, #28a745, #20c997);\r\n            width: 100%;\r\n        }\r\n        .inner-padding {\r\n            padding: 40px;\r\n        }\r\n        .title {\r\n            color: #1a1a1a;\r\n            font-size: 26px;\r\n            font-weight: 700;\r\n            margin-bottom: 20px;\r\n            letter-spacing: -0.5px;\r\n        }\r\n        .content {\r\n            color: #4a4a4a;\r\n            font-size: 16px;\r\n            line-height: 1.7;\r\n            margin-bottom: 30px;\r\n        }\r\n        .button {\r\n            background-color: #28a745;\r\n            color: #ffffff !important;\r\n            padding: 14px 28px;\r\n            text-decoration: none;\r\n            border-radius: 8px;\r\n            font-weight: 600;\r\n            display: inline-block;\r\n            transition: background 0.3s;\r\n        }\r\n        .footer {\r\n            color: #999999;\r\n            font-size: 13px;\r\n            text-align: center;\r\n            padding: 30px;\r\n            background-color: #fcfcfc;\r\n            border-top: 1px solid #eeeeee;\r\n        }\r\n    </style>\r\n</head>\r\n<body>\r\n    <table role=\"presentation\" class=\"wrapper\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">\r\n        <tr>\r\n            <td align=\"center\">\r\n                <table class=\"container\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">\r\n                    <tr><td><div class=\"header-accent\"></div></td></tr>\r\n                    <tr>\r\n                        <td class=\"inner-padding\">\r\n                            <div class=\"title\">\r\n                                Потвърдете имейл адреса си\r\n                            </div>\r\n                            <div class=\"content\">\r\n                                Здравейте, <strong>{{user_name}}</strong>!<br><br>\r\n                                Радваме се, че се регистрирахте при нас! За да започнете да използвате профила си, моля, потвърдете Вашия имейл адрес, като кликнете върху бутона по-долу.\r\n                            </div>\r\n                            <div align=\"center\">\r\n                                <a href=\"{{verification_link}}\" class=\"button\">Потвърди моя имейл</a>\r\n                            </div>\r\n                        </td>\r\n                    </tr>\r\n                    <tr>\r\n                        <td class=\"footer\">\r\n                            Ако не сте се регистрирали в нашата платформа, можете безопасно да игнорирате този имейл.<br>\r\n                            &copy; 2026 Име на Вашата компания\r\n                        </td>\r\n                    </tr>\r\n                </table>\r\n            </td>\r\n        </tr>\r\n    </table>\r\n</body>\r\n</html>', '\"[{\\\"key\\\":\\\"user_name\\\",\\\"label\\\":\\\"\\\\u0418\\\\u043c\\\\u0435 \\\\u043d\\\\u0430 \\\\u043f\\\\u043e\\\\u0442\\\\u0440\\\\u0435\\\\u0431\\\\u0438\\\\u0442\\\\u0435\\\\u043b\\\\u044f (\\\\u043f\\\\u0435\\\\u0440\\\\u0441\\\\u043e\\\\u043d\\\\u0430\\\\u043b\\\\u0438\\\\u0437\\\\u0438\\\\u0440\\\\u0430\\\\u043d\\\\u043e \\\\u043e\\\\u0431\\\\u0440\\\\u044a\\\\u0449\\\\u0435\\\\u043d\\\\u0438\\\\u0435).\\\"},{\\\"key\\\":\\\"verification_link\\\",\\\"label\\\":\\\"\\\\u0423\\\\u043d\\\\u0438\\\\u043a\\\\u0430\\\\u043b\\\\u0435\\\\u043d URL \\\\u0430\\\\u0434\\\\u0440\\\\u0435\\\\u0441, \\\\u043a\\\\u043e\\\\u0439\\\\u0442\\\\u043e \\\\u043d\\\\u0430\\\\u0441\\\\u043e\\\\u0447\\\\u0432\\\\u0430 \\\\u043f\\\\u043e\\\\u0442\\\\u0440\\\\u0435\\\\u0431\\\\u0438\\\\u0442\\\\u0435\\\\u043b\\\\u044f \\\\u043a\\\\u044a\\\\u043c \\\\u0441\\\\u0442\\\\u0440\\\\u0430\\\\u043d\\\\u0438\\\\u0446\\\\u0430\\\\u0442\\\\u0430 \\\\u0437\\\\u0430 \\\\u0432\\\\u0435\\\\u0440\\\\u0438\\\\u0444\\\\u0438\\\\u043a\\\\u0430\\\\u0446\\\\u0438\\\\u044f \\\\u043d\\\\u0430 \\\\u0430\\\\u043a\\\\u0430\\\\u0443\\\\u043d\\\\u0442\\\\u0430 (\\\\u0430\\\\u043a\\\\u0442\\\\u0438\\\\u0432\\\\u0430\\\\u0446\\\\u0438\\\\u043e\\\\u043d\\\\u0435\\\\u043d \\\\u043b\\\\u0438\\\\u043d\\\\u043a).\\\"}]\"');
